<section class="card"><div class="card-header"><h2>Un archivo para cada versión</h2><p>Consulta los documentos de todos los acuerdos.</p></div><form method="get" class="toolbar"><input type="hidden" name="page" value="documents"><label class="sr-only" for="document-q">Buscar documentos</label><input id="document-q" name="q" value="<?= e($q) ?>" placeholder="Cliente, código o nombre del documento"><button class="btn btn-primary">Buscar</button></form></section>
